<?php
require_once __DIR__ . '/../_common.php';
try{$m=api_allow_methods(['GET','POST']);if($m==='GET'){if(empty($_SESSION['id_akun'])||($_SESSION['role']??'')!=='fo')api_reply(401,false,'Belum login sebagai FO.',null);api_reply(200,true,'Sesi FO aktif.',['id_akun'=>(int)$_SESSION['id_akun'],'role'=>'fo','nama'=>$_SESSION['nama']??null]);}$b=api_body();if(($b['action']??'login')==='logout'){if(($_SESSION['role']??'')!=='fo')api_reply(401,false,'Belum login sebagai FO.',null);$_SESSION=[];session_destroy();api_reply(200,true,'Logout berhasil.',null);}$email=api_string($b['email']??null,'email',100);$password=api_string($b['password']??null,'password',255);$s=$conn->prepare("SELECT id_akun,nama,email,password,status_akun FROM akun WHERE email=? AND role='fo' LIMIT 1");$s->bind_param('s',$email);$s->execute();$row=api_one($s);$s->close();if(!$row||$row['status_akun']!=='aktif'||!password_verify($password,(string)$row['password']))api_reply(401,false,'Email atau kata sandi FO salah.',null);session_regenerate_id(true);$_SESSION['id_akun']=(int)$row['id_akun'];$_SESSION['role']='fo';$_SESSION['nama']=$row['nama'];api_reply(200,true,'Login FO berhasil.',['id_akun'=>(int)$row['id_akun'],'nama'=>$row['nama'],'role'=>'fo']);}catch(Throwable $e){api_db_error($e);}